# The real pre-RunPlan schema-three fixture also contains the former populated
# ResponseFitCache. Its three fitted responses were generated by public runs.
old_response_cache_fixture <- function() readRDS(test_path("fixtures", "saved-objects",
    "sceptre-schema3-list-plans-2a0938e.rds"))

test_that("verified schema three response fits migrate losslessly to the unified cache", {
    old <- old_response_cache_fixture()
    physical <- attributes(attr(old, "fits"))
    expect_identical(as.character(physical$class)[1L], "ResponseFitCache")
    expect_length(physical$entries, 3L)
    before <- serialize(old, NULL)
    migrated <- sceptre:::migrate_sceptre_object(old)
    expect_s4_class(migrated@fits, "FitCache")
    expect_identical(migrated@fits@response_fits, physical$entries)
    expect_identical(migrated@fits@response_identity, physical$identity)
    expect_length(migrated@fits@perturbation_fits, 0L)
    expect_length(migrated@fits@perturbation_identity, 0L)
    expect_identical(migrated@schema_version, 3L)
    expect_true(validObject(migrated))
    expect_true(sceptre:::result_record_is_current(migrated, "run_discovery_analysis"))
    expect_identical(migrated@results@records$run_discovery_analysis$table,
        old@results@records$run_discovery_analysis$table)
    expect_identical(migrated@results@records$run_discovery_analysis$identity,
        old@results@records$run_discovery_analysis$identity)
    expect_identical(serialize(old, NULL), before)
    expect_identical(sceptre:::migrate_sceptre_object(migrated), migrated)
    path <- tempfile(fileext = ".rds")
    on.exit(unlink(path), add = TRUE)
    saveRDS(migrated, path)
    expect_identical(sceptre:::migrate_sceptre_object(readRDS(path)), migrated)
})

test_that("unknown or uncertified saved cache layouts are never blessed", {
    old <- old_response_cache_fixture()
    cache <- attr(old, "fits")
    attr(cache, "unexpected_scope") <- list(reusable = TRUE)
    attr(old, "fits") <- cache
    expect_error(sceptre:::migrate_sceptre_object(old), "Unrecognized schema-three fit-cache layout")
    old <- old_response_cache_fixture()
    cache <- attr(old, "fits")
    identity <- attr(cache, "identity")
    identity$data <- "different screen"
    attr(cache, "identity") <- identity
    attr(old, "fits") <- cache
    expect_error(sceptre:::migrate_sceptre_object(old), "Saved response fits do not match")
})
